// Compile the per-bathing-water storm-overflow spill record from the Environment
// Agency's EDM Storm Overflow Annual Returns.
//
// This is not part of `pnpm build`. The returns are a statutory annual
// publication (Environment Act 2021, due by 1 April), so the output is
// generated by hand once a year with `pnpm data:spills` and committed. That
// keeps a 30MB download and a host that 403s datacentre IPs out of the deploy
// path entirely.
//
// England only. The return covers ten water and sewerage companies, nine
// English plus Dwr Cymru, and Dwr Cymru appears only for its overflows on the
// English side of the border. NRW, SEPA and NI Water publish their own
// equivalents, which this does not read.
//
// Two numbers come out of it per bathing water per year:
//
//   attributed  Overflows the EA itself links to that bathing water, in the
//               return's own "Bathing Water(s)" column. Authoritative, because
//               it follows the water rather than the map: it picks up an
//               upstream overflow miles inland and leaves out a nearby one
//               that drains elsewhere. This is the headline figure.
//
//   nearby      Monitored overflows within 10km, the same radius the live
//               verdict uses. Context only, and misleading on its own: a lake
//               in a city collects hundreds of urban overflows that drain
//               nowhere near it.
//
// Spill counts only, deliberately. The duration column is not fit to publish
// without work this does not do: the 2021 to 2023 returns report decimal hours,
// the 2024 and 2025 returns switched to hh:mm:ss, which arrives as an Excel
// time serial this reader hands back as a bare number, and rows in several
// sheets carry stray values such as 4503, 2019 and 2025 that no reading of the
// unit makes plausible. Reconciling it needs per-company calibration against
// each year's summary workbook.
//
// The spill column needs none of that. Its highest single value across five
// years is 366, it carries no strays at all, and the national totals it
// produces reconcile with the figures the EA publishes. A wrong hours figure
// would cost more than a missing one.

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { aliasToSlug } from './lib/bathing-water-aliases.mjs';
import { gridRefToWgs84, haversineMetres } from './lib/ngr.mjs';
import { openWorkbook, readZipEntries } from './lib/xlsx.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '..');
const outFile = resolve(repoRoot, 'src', 'data', 'spill-history.json');
const cacheDir = resolve(here, '.edm-cache');
const locationsFile = resolve(repoRoot, 'src', 'data', 'locations.json');

const YEARS = [2021, 2022, 2023, 2024, 2025];

/**
 * The national spill total the EA published for each return, used to check the
 * parse rather than to produce it. Reconciling against these is the only
 * independent test the ingest has: everything else it could verify against is
 * derived from the same rows it just read.
 *
 * A parse landing within a percent of every one of these has almost certainly
 * read the right column off the right sheets, and a year that drifts is saying
 * the workbook moved under us.
 */
const PUBLISHED_SPILL_TOTALS = {
	2021: 372_533,
	2022: 301_091,
	2023: 464_056,
	2024: 450_398,
	2025: 290_000
};
const TOTALS_TOLERANCE = 0.01;

/**
 * How far an EA-attributed outfall may sit from its bathing water. Attribution
 * follows the sewer network rather than the map, so a genuine link can run well
 * inland: the 95th percentile is around 21km. Beyond this it is a mistake in
 * the return, not a long catchment.
 */
const MAX_ATTRIBUTION_METRES = 50_000;
const RADIUS_METRES = 10_000;
const DATASET_ID = 'c55e170e-3c75-49a5-8026-a961ff94c8e0';
const USER_AGENT = 'isitsafetoswim/0.1 (+https://isitsafetoswim.com)';

// 2020 is deliberately excluded: it ships one workbook per company under a
// different naming scheme, and EDM coverage that year was too partial for the
// totals to sit alongside the rest as a trend.

const NOT_APPLICABLE = new Set(['', 'not applicable', 'n/a', 'na', 'none', 'nil', '-']);

function normalise(value) {
	return String(value ?? '')
		.toLowerCase()
		.normalize('NFKD')
		.replace(/[\u0300-\u036f]/g, '')
		.replace(/[^a-z0-9]+/g, '');
}

async function fetchYear(year) {
	await mkdir(cacheDir, { recursive: true });
	const cached = join(cacheDir, `EDM_${year}.zip`);
	try {
		return await readFile(cached);
	} catch {
		// not cached yet
	}
	const name = `EDM_${year}_Storm_Overflow_Annual_Return.zip`;
	const url = `https://environment.data.gov.uk/api/file/download?fileDataSetId=${DATASET_ID}&fileName=${encodeURIComponent(name)}`;
	process.stdout.write(`  downloading ${year}... `);
	const res = await fetch(url, { headers: { 'user-agent': USER_AGENT } });
	if (!res.ok) throw new Error(`EDM ${year} download failed: ${res.status}`);
	const buffer = Buffer.from(await res.arrayBuffer());
	await writeFile(cached, buffer);
	process.stdout.write(`${(buffer.length / 1e6).toFixed(1)}MB\n`);
	return buffer;
}

/** The annual zip holds the combined workbook plus summary files we do not want. */
function workbookFor(year, zipBuffer) {
	const entries = readZipEntries(zipBuffer);
	const match = [...entries.keys()].find(
		(name) => name.endsWith('.xlsx') && /all water and sewerage/i.test(name) && !/summary/i.test(name)
	);
	if (!match) throw new Error(`EDM ${year}: no combined workbook in the archive`);
	return openWorkbook(entries.get(match));
}

/**
 * Resolve columns by header text rather than position. Both the position and
 * the sheet names move between years, but the wording of these headers has held
 * since 2021.
 */
function resolveColumns(headerRow) {
	const columns = {};
	headerRow.forEach((raw, index) => {
		const header = String(raw ?? '')
			.replace(/\s+/g, ' ')
			.trim();
		if (/^Outlet Discharge NGR/i.test(header)) columns.gridRef = index;
		else if (/^Bathing Water/i.test(header)) columns.bathingWater = index;
		else if (/^Counted spills/i.test(header)) columns.spills = index;
		else if (/^Water Company Name/i.test(header)) columns.company = index;
	});
	return columns;
}

function findHeaderRow(rows) {
	for (let i = 0; i < Math.min(20, rows.length); i += 1) {
		if (rows[i].some((cell) => /^Outlet Discharge NGR/i.test(String(cell ?? '').trim()))) return i;
	}
	return -1;
}

/**
 * No overflow can be counted spilling on more days than the year holds, and the
 * highest value anywhere in the 2021 to 2025 returns is 366. Nothing in this
 * column has ever exceeded the bound, so a value that does means the column has
 * been resolved onto the wrong field, which is a reason to stop rather than to
 * quietly publish a zero.
 */
const MAX_SPILLS_PER_YEAR = 400;

/**
 * A spill count, or null where the return does not give one. The distinction
 * matters: 847 rows in the 2021 return carry "N/A", "#N/A" or "-", meaning the
 * overflow was not monitored, and reading those as zero understates the year
 * and then reappears as a fictitious rise in the trend on the page.
 */
function parseSpills(value) {
	const raw = String(value ?? '').trim();
	if (!raw) return null;
	const n = Number(raw);
	if (!Number.isFinite(n)) return null;
	if (n > MAX_SPILLS_PER_YEAR) {
		throw new Error(
			`counted spills of ${n} exceeds the ${MAX_SPILLS_PER_YEAR} bound; ` +
				'the spills column has probably been resolved onto the wrong field'
		);
	}
	return n < 0 ? null : n;
}

function tidyName(part) {
	return (
		part
			.trim()
			.replace(/^and\s+/i, '')
			// Footnote markers trail some names, as in "...SANDSFOOT CASTLE**".
			.replace(/\*+$/, '')
			.trim()
	);
}

/**
 * Names in the bathing-water cell, in the order they should be tried.
 *
 * The separator is not fixed, and getting it wrong quietly attributes spills to
 * the wrong beach. Southern Water writes "Botany Bay, Broadstairs; Joss Bay,
 * Broadstairs": semicolons divide the names and the commas are inside them.
 * Splitting on commas there turns two bathing waters into four, two of which
 * are the wrong ones. Plenty of bathing waters carry a comma of their own,
 * Whitmore Bay, Barry Island among them.
 *
 * So: a cell holding a semicolon is a semicolon-separated list and its commas
 * are left alone. Otherwise the cell is offered whole first, and only broken on
 * commas if it does not resolve as a single name.
 *
 * Purely numeric values are dropped. Several companies filled this column with
 * figures rather than names in the earlier returns, Thames Water putting "0"
 * against all 465 of its 2021 overflows, and a bathing water is never a number.
 */
function splitBathingWaters(cell) {
	const usable = (part) => part && !NOT_APPLICABLE.has(part.toLowerCase()) && !/^[\d.]+$/.test(part);
	if (NOT_APPLICABLE.has(cell.toLowerCase())) return { whole: null, parts: [] };

	const whole = tidyName(cell.replace(/\//g, ';').split(';')[0]);
	if (cell.includes(';') || cell.includes('/')) {
		return {
			whole: null,
			parts: cell.replace(/\//g, ';').split(';').map(tidyName).filter(usable)
		};
	}
	return {
		whole: usable(whole) ? whole : null,
		parts: cell.split(',').map(tidyName).filter(usable)
	};
}

/**
 * The outfall position. Some cells name two, as "NZ5047635589 / NZ5053835695"
 * or "NZ1923451825 (to a culverted watercourse which opens at NZ1972351654)".
 * Taking the first recovers 23 to 71 rows a year, carrying several hundred
 * spills between them, that a whole-cell parse would drop. The two references
 * in such a cell are always a few hundred metres apart, well inside the
 * tolerance of a ten-kilometre radius.
 */
function firstGridRef(cell) {
	const whole = gridRefToWgs84(cell.trim());
	if (whole) return whole;
	for (const candidate of cell.toUpperCase().match(/[A-HJ-Z]{2}\s?\d{4,10}/g) ?? []) {
		const point = gridRefToWgs84(candidate);
		if (point) return point;
	}
	return null;
}

function readYear(workbook, year) {
	const rows = [];
	// 2025 added an "All WaSC" aggregate alongside the per-company sheets. Taking
	// both would double every figure, so the aggregate is skipped whenever any
	// per-company sheet is present.
	const perCompany = workbook.sheetNames.filter((name) => !/^all wasc/i.test(name));
	const sheets = perCompany.length > 0 ? perCompany : workbook.sheetNames;

	for (const sheetName of sheets) {
		const sheet = workbook.rowsOf(sheetName);
		const headerIndex = findHeaderRow(sheet);
		if (headerIndex < 0) continue;
		const columns = resolveColumns(sheet[headerIndex]);
		if (columns.gridRef === undefined || columns.spills === undefined) continue;

		// A sheet carries notes and totals below its table, and those rows hold
		// stray figures: years, counts, blanks. Anchoring on a parseable grid
		// reference keeps them out, which matters twice over, because otherwise
		// a stray "2025" reads as a duration and a stray "178" as a bathing water.
		const body = [];
		for (const row of sheet.slice(headerIndex + 1)) {
			const point = firstGridRef(String(row[columns.gridRef] ?? ''));
			if (point) body.push({ row, point });
		}

		for (const { row, point } of body) {
			const bathingWater = String(row[columns.bathingWater] ?? '').trim();
			rows.push({
				year,
				point,
				company: String(row[columns.company] ?? '').trim(),
				spills: parseSpills(row[columns.spills]),
				bathingWaters: splitBathingWaters(bathingWater)
			});
		}
	}
	return rows;
}

function blank() {
	return { overflows: 0, spills: 0, unmonitored: 0 };
}

function add(total, row) {
	total.overflows += 1;
	if (row.spills === null) total.unmonitored += 1;
	else total.spills += row.spills;
}

/**
 * `unmonitored` rides along so the page can tell a quiet year from an unmeasured
 * one. It is omitted when zero, which is the usual case, to keep the file small.
 */
function round(total) {
	const out = { overflows: total.overflows, spills: Math.round(total.spills) };
	if (total.unmonitored > 0) out.unmonitored = total.unmonitored;
	return out;
}

async function main() {
	const catalogue = JSON.parse(await readFile(locationsFile, 'utf8')).locations;
	const english = catalogue.filter((l) => l.country === 'England');

	// Index the catalogue by every name the EA might use for it, plus the
	// curated aliases for the ones whose wording differs from ours.
	const bySlug = new Map(catalogue.map((l) => [l.slug, l]));
	const byName = new Map();
	for (const location of catalogue) {
		for (const name of [location.name, location.officialName]) {
			if (name) byName.set(normalise(name), location);
		}
	}
	/**
	 * Match one EA name against the catalogue. Tried in order of confidence: the
	 * curated alias, then the name as written, then two mechanical variants that
	 * account for how the return writes names. "CRANTOCK BEACH" is our Crantock,
	 * and "PLYMOUTH HOE (EAST & WEST)" carries a parenthetical the catalogue
	 * does not. Each variant only counts when it lands on a real bathing water,
	 * so a stripped name that matches nothing changes nothing.
	 */
	const lookup = (name) => {
		const key = normalise(name);
		const aliased = aliasToSlug[key];
		if (aliased) return bySlug.get(aliased) ?? null;
		if (byName.has(key)) return byName.get(key);
		const withoutParens = normalise(name.replace(/\([^)]*\)/g, ''));
		if (withoutParens && byName.has(withoutParens)) return byName.get(withoutParens);
		const withoutBeach = key.replace(/beach$/, '');
		if (withoutBeach && withoutBeach !== key && byName.has(withoutBeach)) {
			return byName.get(withoutBeach);
		}
		return null;
	};

	/**
	 * Resolve one EA name to bathing waters we hold. Usually one, but the EA
	 * sometimes names two in a single cell joined by "and" or "&", as in
	 * "Newbiggin North & Newbiggin South". That is only attempted once the whole
	 * string has failed, because splitting first would break the bathing waters
	 * carrying a conjunction in their own name: Newton and Noss is one site.
	 */
	const resolveBathingWater = (name) => {
		const direct = lookup(name);
		if (direct) return [direct];
		if (!/\s(?:and|&)\s/i.test(name)) return [];
		const parts = name.split(/\s(?:and|&)\s/i).map((part) => lookup(part.trim()));
		return parts.every(Boolean) ? parts : [];
	};

	const perYear = new Map();
	const unmatchedNames = new Map();
	const implausible = [];
	for (const year of YEARS) {
		const workbook = workbookFor(year, await fetchYear(year));
		const rows = readYear(workbook, year);
		perYear.set(year, rows);
		const spills = rows.reduce((sum, r) => sum + r.spills, 0);
		console.log(
			`  ${year}: ${rows.length.toLocaleString('en-GB')} overflows, ` +
				`${Math.round(spills).toLocaleString('en-GB')} spills`
		);
	}

	// Spatial buckets, so each bathing water only measures against overflows in
	// its own neighbourhood rather than all 14,000. A 0.2 degree cell is about
	// 12.5km across at the top of England, so searching the eight neighbours
	// covers the 10km radius with margin. Raising RADIUS_METRES past that would
	// need a wider search or a smaller cell.
	const cell = (lat, lon) => `${Math.round(lat / 0.2)}:${Math.round(lon / 0.2)}`;

	const output = {};
	const attributionDistances = [];
	let attributedBeaches = 0;
	let nearbyBeaches = 0;

	for (const year of YEARS) {
		const rows = perYear.get(year);
		const grid = new Map();
		for (const row of rows) {
			const key = cell(row.point.lat, row.point.lon);
			if (!grid.has(key)) grid.set(key, []);
			grid.get(key).push(row);
		}

		const attributedByLocation = new Map();
		for (const row of rows) {
			// The whole cell is tried as one name before its parts, so a bathing
			// water whose own name carries a comma is not broken into pieces.
			const { whole, parts } = row.bathingWaters;
			const names = whole && resolveBathingWater(whole).length > 0 ? [whole] : parts;
			for (const name of names) {
				const locations = resolveBathingWater(name);
				if (locations.length === 0) {
					unmatchedNames.set(name, (unmatchedNames.get(name) ?? 0) + 1);
					continue;
				}
				for (const location of locations) {
					// The EA return carries the occasional attribution to a beach in
					// another region: Southern Water tags an Isle of Wight outfall to
					// Seaton Carew, 432km away in Hartlepool. A sewer does not run that
					// far, so beyond this bound the row is a data error rather than an
					// upstream link, and counting it would put another town's spills on
					// this beach's record.
					const metres = haversineMetres({ lat: location.lat, lon: location.lon }, row.point);
					if (metres > MAX_ATTRIBUTION_METRES) {
						implausible.push({ metres, name, slug: location.slug });
						continue;
					}
					if (!attributedByLocation.has(location.slug)) attributedByLocation.set(location.slug, []);
					attributedByLocation.get(location.slug).push(row);
					attributionDistances.push({ metres, name, slug: location.slug });
				}
			}
		}

		for (const location of english) {
			output[location.slug] ??= { attributed: [], nearby: [] };
			const entry = output[location.slug];

			const attributed = attributedByLocation.get(location.slug);
			if (attributed?.length) {
				const total = blank();
				for (const row of attributed) add(total, row);
				entry.attributed.push({ year, ...round(total) });
			}

			const near = blank();
			const centre = { lat: location.lat, lon: location.lon };
			const [cy, cx] = cell(location.lat, location.lon).split(':').map(Number);
			for (let dy = -1; dy <= 1; dy += 1) {
				for (let dx = -1; dx <= 1; dx += 1) {
					for (const row of grid.get(`${cy + dy}:${cx + dx}`) ?? []) {
						if (haversineMetres(centre, row.point) <= RADIUS_METRES) add(near, row);
					}
				}
			}
			if (near.overflows > 0) entry.nearby.push({ year, ...round(near) });
		}
	}

	for (const entry of Object.values(output)) {
		if (entry.attributed.length > 0) attributedBeaches += 1;
		if (entry.nearby.length > 0) nearbyBeaches += 1;
	}
	// A bathing water with neither figure carries no record, so drop it rather
	// than ship an empty object the page would have to guard against.
	for (const [slug, entry] of Object.entries(output)) {
		if (entry.attributed.length === 0 && entry.nearby.length === 0) delete output[slug];
	}

	attributionDistances.sort((a, b) => a.metres - b.metres);
	const at = (q) => attributionDistances[Math.floor(attributionDistances.length * q)];
	const median = at(0.5)?.metres ?? 0;
	const p95 = at(0.95)?.metres ?? 0;

	console.log('');
	console.log(`  attributed by the EA to a bathing water we hold: ${attributedBeaches}`);
	console.log(
		`  with an overflow within 10km:                    ${nearbyBeaches} of ${english.length} English sites`
	);
	console.log(
		`  attributed outfall-to-beach distance:            median ${(median / 1000).toFixed(2)}km, p95 ${(p95 / 1000).toFixed(1)}km`
	);
	// An outfall attributed to a beach it sits nowhere near is either a bad
	// alias or a bad conversion, and neither shows up in a median.
	const worst = attributionDistances.slice(-5).reverse();
	if (worst.length > 0) {
		console.log('  furthest attributions (check for a mismatched alias):');
		for (const entry of worst) {
			console.log(
				`      ${(entry.metres / 1000).toFixed(0).padStart(4)}km  ${entry.name} -> ${entry.slug}`
			);
		}
	}
	if (implausible.length > 0) {
		console.log(`  attributions dropped as too far to be a sewer: ${implausible.length}`);
		for (const entry of implausible.slice(0, 5)) {
			console.log(
				`      ${(entry.metres / 1000).toFixed(0).padStart(4)}km  ${entry.name} -> ${entry.slug}`
			);
		}
	}
	if (unmatchedNames.size > 0) {
		const top = [...unmatchedNames.entries()].sort((a, b) => b[1] - a[1]).slice(0, 15);
		console.log(`  EA names we could not resolve: ${unmatchedNames.size}`);
		for (const [name, count] of top) console.log(`      ${count.toString().padStart(4)}  ${name}`);
	}

	// Guards. The grid conversion is the one step with no independent check in
	// the data, so a silent regression there would quietly relocate every
	// outfall. If the EA's own attributions stop landing near their beach, the
	// maths has broken and the output must not be written.
	for (const year of YEARS) {
		const rows = perYear.get(year);
		const parsed = rows.reduce((sum, r) => sum + (r.spills ?? 0), 0);
		const published = PUBLISHED_SPILL_TOTALS[year];
		if (rows.length < 10_000) {
			throw new Error(
				`EDM ${year} yielded only ${rows.length} overflows; a sheet was probably skipped`
			);
		}
		if (published && Math.abs(parsed - published) / published > TOTALS_TOLERANCE) {
			throw new Error(
				`EDM ${year} parsed ${parsed} spills against ${published} published, ` +
					`a ${((Math.abs(parsed - published) / published) * 100).toFixed(1)}% gap`
			);
		}
	}
	if (attributionDistances.length < 500) {
		throw new Error(`only ${attributionDistances.length} EA attributions resolved; expected 500+`);
	}
	if (median > 5000) {
		throw new Error(
			`median attributed outfall sits ${(median / 1000).toFixed(1)}km from its bathing water; ` +
				'the grid-reference conversion has probably regressed'
		);
	}
	if (nearbyBeaches < english.length * 0.9) {
		throw new Error(`only ${nearbyBeaches} of ${english.length} English sites got a record`);
	}

	await writeFile(
		outFile,
		`${JSON.stringify(
			{
				generatedAt: new Date().toISOString(),
				source: 'Environment Agency EDM Storm Overflow Annual Returns',
				licence: 'Open Government Licence v3.0',
				coverage: 'England',
				radiusMetres: RADIUS_METRES,
				years: YEARS,
				bySlug: output
			},
			null,
			'\t'
		)}\n`
	);
	console.log(`\n  wrote ${outFile}`);
}

main().catch((error) => {
	console.error(error);
	process.exit(1);
});
